css:
.mode {
  position: relative;
  display: inline-block;
  width: 116px;
  height: 44px;
  cursor: pointer;
  user-select: none;
  font-family: "Trebuchet MS", sans-serif;
}

.mode input {
  display: none;
}

.track {
  position: absolute;
  top: 0;
  left: 0;
  width: 78px;
  height: 44px;
  border-radius: 22px;
  background: #ef4655;
  transition: 0.4s ease;
}

.button {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 3px 7px rgba(0, 0, 0, 0.2);
  transition: transform 0.45s cubic-bezier(0.6, -0.25, 0.3, 1.25);
}

.button:after {
  content: "";
  position: absolute;
  width: 14px;
  height: 14px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: #ef4655;
  transition: 0.35s ease;
}

.letter-f,
.external-letter {
  font-family: inherit;
  font-size: 40px;
  font-weight: 1000;
  line-height: 36px;
}

.letter-f {
  position: absolute;
  left: 45px;
  top: 4px;
  color: white;
  transition: 0.3s ease;
}

.external-letter {
  position: absolute;
  left: 84px;
  top: 4px;
  color: #00bd61;
  transition: 0.3s ease;
}

.mode input:checked + .track {
  background: #00bd61;
}

.mode input:checked + .track .button {
  transform: translateX(34px);
}

.mode input:checked + .track .button:after {
  background: #00bd61;
  transform: translate(-50%, -50%) scale(0.9);
}

.mode input:checked + .track .letter-f {
  opacity: 0;
  transform: translateX(-7px);
}

.mode input:checked ~ .external-letter {
  color: #00bd61;
}

.mode input:not(:checked) ~ .external-letter {
  color: #ef4655;
  font-size: 0;
}

.mode input:not(:checked) ~ .external-letter:after {
  content: "F";
  font-family: inherit;
  font-size: 40px;
  font-weight: 1000;
  line-height: 36px;
  color: #ef4655;
}

.mode:hover .button {
  box-shadow:
    0 4px 8px rgba(0, 0, 0, 0.2),
    0 8px 16px rgba(0, 0, 0, 0.12),
    inset 0 1px 1px rgba(255, 255, 255, 0.8);
}

.mode:active .button {
  transform: scale(0.92);
}

.mode input:checked + .track:active .button {
  transform: translateX(34px) scale(0.92);
}
